// src/pages/AIWrite.js

import { useState } from "react";

import {
  FiSearch,
  FiCamera,
} from "react-icons/fi";

// ==================================================
// ★ Tesseract.js
//
// 브라우저에서 바로 OCR을 돌리는 라이브러리
// API 키 / 결제계정 / 백엔드 없이 동작함
//
// 설치: npm install tesseract.js
// ==================================================

import Tesseract from "tesseract.js";

// ==================================================
// ★ 백엔드 주소
//
// 나중에 실제 배포 주소로 바꾸면 됨
// ==================================================

const API_BASE_URL =
  "http://localhost:8080";

function AIWrite() {
  const [searched, setSearched] =
    useState(false);

  const [selected, setSelected] =
    useState(false);

  // ==================================================
  // 느낀점
  // ==================================================

  const [feeling, setFeeling] =
    useState("");

  // ==================================================
  // AI 독후감 생성 결과 / 상태
  // ==================================================

  const [generated, setGenerated] =
    useState(false);

  const [
    generatedText,
    setGeneratedText,
  ] = useState("");

  const [
    generateLoading,
    setGenerateLoading,
  ] = useState(false);

  const [
    generateError,
    setGenerateError,
  ] = useState("");

  // ==================================================
  // OCR 관련
  // ==================================================

  const [image, setImage] =
    useState(null);

  const [ocrText, setOcrText] =
    useState("");

  const [ocrLoading, setOcrLoading] =
    useState(false);

  // ------------------------------------------
  // ★ 진행률 (Tesseract는 시간이 좀 걸려서
  // 로딩 중임을 % 로 보여주면 훨씬 자연스러움
  // ------------------------------------------

  const [ocrProgress, setOcrProgress] =
    useState(0);

  const [ocrError, setOcrError] =
    useState("");

  // =========================
  // ★ OCR 실행 (Tesseract.js)
  //
  // - 한국어 + 영어 동시 인식: "kor+eng"
  // - 처음 실행할 때 한국어 언어팩(kor.traineddata)을
  //   자동으로 다운로드하기 때문에 첫 실행은 느릴 수 있음
  //   (발표 전에 한 번 미리 실행해서 캐싱해두면 좋음)
  // =========================

  const runOCR = async (file) => {
    if (!file) return;

    setOcrLoading(true);
    setOcrProgress(0);
    setOcrError("");
    setOcrText("");

    try {
      const result =
        await Tesseract.recognize(
          file,
          "kor+eng",
          {
            logger: (message) => {
              // ------------------------------------------
              // Tesseract가 진행 상황을 계속 콜백으로 알려줌
              // status: 'recognizing text' 일 때 progress 사용
              // ------------------------------------------

              if (
                message.status ===
                "recognizing text"
              ) {
                setOcrProgress(
                  Math.round(
                    message.progress *
                      100
                  )
                );
              }
            },
          }
        );

      const text =
        result?.data?.text?.trim() ||
        "";

      if (!text) {
        setOcrError(
          "사진에서 텍스트를 찾지 못했어요."
        );

        return;
      }

      setOcrText(text);
    } catch (error) {
      console.error(
        "OCR 오류:",
        error
      );

      setOcrError(
        "OCR 처리 중 오류가 발생했습니다."
      );
    } finally {
      setOcrLoading(false);
    }
  };

  // =========================
  // 사진 선택
  // =========================

  const handleImageChange = (
    event
  ) => {
    const file =
      event.target.files?.[0];

    if (!file) return;

    setImage(
      URL.createObjectURL(file)
    );

    runOCR(file);
  };

  // =========================
  // AI 독후감 생성 요청
  //
  // OCR로 뽑은 구절(ocrText) +
  // 책 정보 + 느낀점을
  // 백엔드로 String 형태로 전달
  // =========================

  const handleGenerate = async () => {
    if (generateLoading) {
      return;
    }

    setGenerateLoading(true);
    setGenerateError("");
    setGenerated(false);

    const requestData = {
      bookTitle: "노르웨이의 숲",
      bookAuthor: "무라카미 하루키",

      quote: ocrText,

      feeling: feeling,
    };

    console.log(
      "AI 독후감 생성 요청 데이터:",
      requestData
    );

    try {
      const response = await fetch(
        `${API_BASE_URL}/api/reviews/ai-generate`,
        {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json",
          },

          body: JSON.stringify(
            requestData
          ),
        }
      );

      if (!response.ok) {
        throw new Error(
          "독후감 생성 요청에 실패했습니다."
        );
      }

      const data =
        await response.json();

      setGeneratedText(
        data.review || ""
      );

      setGenerated(true);
    } catch (error) {
      console.error(
        "AI 독후감 생성 오류:",
        error
      );

      setGenerateError(
        error.message ||
          "독후감 생성 중 오류가 발생했습니다."
      );
    } finally {
      setGenerateLoading(false);
    }
  };

  return (
    <div className="page">
      {/* 상단 */}

      <div className="top-bar">
        <div className="logo">
          READLY
        </div>
      </div>

      <div className="line"></div>

      {/* 제목 */}

      <div className="write-top">
        <div className="write-title">
          AI 독후감 작성
        </div>

        <div className="write-sub">
          책과 감상을 기록해보세요
        </div>
      </div>

      {/* 책 검색 */}

      <div className="write-card">
        <div className="input-label">
          어떤 책을 읽었나요?
        </div>

        <div className="book-search">
          <FiSearch />

          <input
            placeholder="책 제목 검색하기"
            onChange={() =>
              setSearched(true)
            }
          />
        </div>

        {/* 검색 결과 */}

        {searched && !selected && (
          <div
            className="search-item"
            onClick={() =>
              setSelected(true)
            }
          >
            <div className="search-cover">
              📘
            </div>

            <div>
              <div className="book-name">
                노르웨이의 숲
              </div>

              <div className="book-author">
                무라카미 하루키
              </div>
            </div>
          </div>
        )}

        {/* 선택된 책 */}

        {selected && (
          <div className="book-result">
            <div className="book-cover">
              📘
            </div>

            <div>
              <div className="book-name">
                노르웨이의 숲
              </div>

              <div className="book-author">
                무라카미 하루키
              </div>
            </div>
          </div>
        )}
      </div>

      {/* 인상 깊은 구절 */}

      <div className="write-card">
        <div className="input-label">
          인상 깊은 구절
        </div>

        <textarea
          className="write-textarea"
          placeholder="기억에 남는 문장을 적어보세요"
          value={ocrText}
          onChange={(e) =>
            setOcrText(
              e.target.value
            )
          }
        ></textarea>

        {/* 사진 업로드 */}

        <input
          id="book-photo"
          type="file"
          accept="image/*"
          capture="environment"
          style={{
            display: "none",
          }}
          onChange={
            handleImageChange
          }
        />

        <label
          htmlFor="book-photo"
          className="photo-btn"
        >
          <FiCamera />

          {ocrLoading
            ? `텍스트를 읽는 중... ${ocrProgress}%`
            : "책 구절 사진 찍기"}
        </label>

        {/* 사진 미리보기 */}

        {image && (
          <div
            style={{
              marginTop: "14px",
            }}
          >
            <img
              src={image}
              alt="책 구절"
              style={{
                width: "100%",
                maxHeight: "300px",
                objectFit: "contain",
                borderRadius: "12px",
              }}
            />
          </div>
        )}

        {/* OCR 오류 */}

        {ocrError && (
          <div
            style={{
              marginTop: "10px",
              color: "#e57373",
              fontSize: "13px",
            }}
          >
            {ocrError}
          </div>
        )}

        {/* OCR 완료 */}

        {ocrText &&
          !ocrLoading && (
            <div
              style={{
                marginTop: "10px",
                fontSize: "12px",
                color: "#888",
              }}
            >
              ✨ 사진에서 텍스트를
              추출했어요.
              <br />
              필요한 부분은 직접
              수정할 수 있어요.
            </div>
          )}
      </div>

      {/* 느낀점 */}

      <div className="write-card">
        <div className="input-label">
          느낀점
        </div>

        <textarea
          className="write-textarea big"
          placeholder="책을 읽고 어떤 생각이 들었나요?"
          value={feeling}
          onChange={(e) =>
            setFeeling(
              e.target.value
            )
          }
        ></textarea>
      </div>

      {/* 생성 버튼 */}

      <button
        className="generate-btn"
        onClick={handleGenerate}
        disabled={generateLoading}
      >
        {generateLoading
          ? "AI가 독후감을 쓰고 있어요..."
          : "AI 독후감 생성하기"}
      </button>

      {/* 생성 오류 */}

      {generateError && (
        <div
          style={{
            marginTop: "10px",
            color: "#e57373",
            fontSize: "13px",
          }}
        >
          {generateError}
        </div>
      )}

      {/* 결과 */}

      {generated && (
        <div className="result-card">
          <div className="result-title">
            ✨ AI 독후감
          </div>

          <div className="result-content">
            {generatedText}
          </div>
        </div>
      )}
    </div>
  );
}

export default AIWrite;
